CREATE TABLE semio_drawing_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, width REAL, height REAL, background_r REAL, background_g REAL, background_b REAL, background_a REAL, width_ieee754_bits INTEGER, width_numeric_class TEXT, height_ieee754_bits INTEGER, height_numeric_class TEXT, background_r_ieee754_bits INTEGER, background_r_numeric_class TEXT, background_g_ieee754_bits INTEGER, background_g_numeric_class TEXT, background_b_ieee754_bits INTEGER, background_b_numeric_class TEXT, background_a_ieee754_bits INTEGER, background_a_numeric_class TEXT);
CREATE TABLE semio_drawing_style (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_drawing_document(id), ordinal INTEGER NOT NULL, name TEXT NOT NULL, fill_r REAL, fill_g REAL, fill_b REAL, fill_a REAL, stroke_r REAL, stroke_g REAL, stroke_b REAL, stroke_a REAL, stroke_width REAL, opacity REAL, fill_r_ieee754_bits INTEGER, fill_r_numeric_class TEXT, fill_g_ieee754_bits INTEGER, fill_g_numeric_class TEXT, fill_b_ieee754_bits INTEGER, fill_b_numeric_class TEXT, fill_a_ieee754_bits INTEGER, fill_a_numeric_class TEXT, stroke_r_ieee754_bits INTEGER, stroke_r_numeric_class TEXT, stroke_g_ieee754_bits INTEGER, stroke_g_numeric_class TEXT, stroke_b_ieee754_bits INTEGER, stroke_b_numeric_class TEXT, stroke_a_ieee754_bits INTEGER, stroke_a_numeric_class TEXT, stroke_width_ieee754_bits INTEGER, stroke_width_numeric_class TEXT, opacity_ieee754_bits INTEGER, opacity_numeric_class TEXT);
CREATE TABLE semio_drawing_layer (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_drawing_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL, visible INTEGER NOT NULL, root_node_id INTEGER NOT NULL REFERENCES semio_drawing_node(id));
CREATE TABLE semio_drawing_node (id INTEGER PRIMARY KEY, kind TEXT NOT NULL);
CREATE TABLE semio_drawing_path (id INTEGER PRIMARY KEY REFERENCES semio_drawing_node(id), style_id INTEGER REFERENCES semio_drawing_style(id));
CREATE TABLE semio_drawing_text (id INTEGER PRIMARY KEY REFERENCES semio_drawing_node(id), text TEXT NOT NULL, x REAL, y REAL, style_id INTEGER REFERENCES semio_drawing_style(id), x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_drawing_group (id INTEGER PRIMARY KEY REFERENCES semio_drawing_node(id), translation_x REAL, translation_y REAL, translation_z REAL, rotation_x REAL, rotation_y REAL, rotation_z REAL, rotation_w REAL, scale_x REAL, scale_y REAL, scale_z REAL, translation_x_ieee754_bits INTEGER, translation_x_numeric_class TEXT, translation_y_ieee754_bits INTEGER, translation_y_numeric_class TEXT, translation_z_ieee754_bits INTEGER, translation_z_numeric_class TEXT, rotation_x_ieee754_bits INTEGER, rotation_x_numeric_class TEXT, rotation_y_ieee754_bits INTEGER, rotation_y_numeric_class TEXT, rotation_z_ieee754_bits INTEGER, rotation_z_numeric_class TEXT, rotation_w_ieee754_bits INTEGER, rotation_w_numeric_class TEXT, scale_x_ieee754_bits INTEGER, scale_x_numeric_class TEXT, scale_y_ieee754_bits INTEGER, scale_y_numeric_class TEXT, scale_z_ieee754_bits INTEGER, scale_z_numeric_class TEXT);
CREATE TABLE semio_drawing_child (id INTEGER PRIMARY KEY, group_id INTEGER NOT NULL REFERENCES semio_drawing_group(id), ordinal INTEGER NOT NULL, node_id INTEGER NOT NULL REFERENCES semio_drawing_node(id));
CREATE TABLE semio_drawing_image (id INTEGER PRIMARY KEY REFERENCES semio_drawing_node(id), x REAL, y REAL, width REAL, height REAL, mime TEXT NOT NULL, bytes BLOB NOT NULL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, width_ieee754_bits INTEGER, width_numeric_class TEXT, height_ieee754_bits INTEGER, height_numeric_class TEXT);
CREATE TABLE semio_drawing_segment (id INTEGER PRIMARY KEY, path_id INTEGER NOT NULL REFERENCES semio_drawing_path(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL);
CREATE TABLE semio_drawing_move (id INTEGER PRIMARY KEY REFERENCES semio_drawing_segment(id), x REAL, y REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_drawing_line (id INTEGER PRIMARY KEY REFERENCES semio_drawing_segment(id), x REAL, y REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_drawing_cubic (id INTEGER PRIMARY KEY REFERENCES semio_drawing_segment(id), c1_x REAL, c1_y REAL, c2_x REAL, c2_y REAL, x REAL, y REAL, c1_x_ieee754_bits INTEGER, c1_x_numeric_class TEXT, c1_y_ieee754_bits INTEGER, c1_y_numeric_class TEXT, c2_x_ieee754_bits INTEGER, c2_x_numeric_class TEXT, c2_y_ieee754_bits INTEGER, c2_y_numeric_class TEXT, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_drawing_quad (id INTEGER PRIMARY KEY REFERENCES semio_drawing_segment(id), c_x REAL, c_y REAL, x REAL, y REAL, c_x_ieee754_bits INTEGER, c_x_numeric_class TEXT, c_y_ieee754_bits INTEGER, c_y_numeric_class TEXT, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_drawing_arc (id INTEGER PRIMARY KEY REFERENCES semio_drawing_segment(id), rx REAL, ry REAL, x_rotation REAL, large_arc INTEGER NOT NULL, sweep INTEGER NOT NULL, x REAL, y REAL, rx_ieee754_bits INTEGER, rx_numeric_class TEXT, ry_ieee754_bits INTEGER, ry_numeric_class TEXT, x_rotation_ieee754_bits INTEGER, x_rotation_numeric_class TEXT, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_drawing_close (id INTEGER PRIMARY KEY REFERENCES semio_drawing_segment(id));
